    answer: "-3",
    mode: "constructed_response",
    difficulty: 2,
    problemType: "cn_g7_absolute_value_sum",
    sequence: 31124,
    solution: "|-8| = 8，|3 - 9| = |-6| = 6，所以原式为 8 - 5 - 6 = -3。"
