const expandedSubjectiveSamples: SubjectiveSample[] = [
  ...expansionSpecs,
  ...chapterExpansionSpecs,
  ...chapterExpansionBatch2Specs,
  ...chapterExpansionBatch3Specs,
  ...chapterExpansionBatch4Specs,
  ...chapterExpansionBatch5Specs,
  ...chapterExpansionBatch6Specs,
  ...chapterExpansionBatch7Specs,
  ...chapterExpansionBatch8Specs,
  ...chapterExpansionBatch9Specs,
  ...seniorHighBatch1Specs,
  ...seniorHighBatch2Specs,
  ...seniorHighBatch3Specs,
  ...seniorHighBatch4Specs,
  ...seniorHighBatch5Specs
].map((spec) => ({
  id: spec.id,
  statement: spec.statement,
  answer: spec.answer,
  answerType: "manual",
  choices: [],
  distractors: [],
  difficulty: spec.difficulty,
  source: "Subjective samples v0",
  primaryConcept: spec.primaryConcept,
  concepts: spec.concepts,
  prerequisiteConcepts: spec.prerequisiteConcepts,
  skills: spec.skills,
  patterns: spec.patterns,
  misconceptions: spec.misconceptions,
  isAutoGradable: false,
  solution: spec.solution,
  responseSchema: subjectiveSchema(spec.mode, rubricForMode(spec.mode)),
  taxonomy: taxonomy(spec.layer, spec.stage, spec.problemType, spec.cognitiveTags, spec.time),
  curriculum: curriculum(spec.course ?? "CN Junior High Math", spec.theme, spec.chapter, spec.chapterTitle, spec.sequence),
  locale: locale("zh", "CN", "中文校内", spec.gradeBand ?? "初中", "pilot"),
  explanation: spec.explanation
}));

const allSamples = [...samples, ...expandedSubjectiveSamples];

function main() {
  const existingProblems = readJson<Problem[]>(PROBLEMS_PATH);
  const existingExplanations = readJson<Record<string, ExampleExplanation>>(EXPLANATIONS_PATH);
  const incomingProblems = stratifyChineseSubjectiveProblems(
    allSamples.map(({ explanation, ...problem }) => problem)
  );
  const incomingIds = new Set(incomingProblems.map((problem) => problem.id));
  const nextProblems = [
    ...existingProblems.filter((problem) => !incomingIds.has(problem.id)),
    ...incomingProblems
  ].sort((a, b) => (a.curriculum?.sequence ?? 0) - (b.curriculum?.sequence ?? 0) || a.id.localeCompare(b.id));
  const nextExplanations = {
    ...existingExplanations,
    ...Object.fromEntries(allSamples.map((sample) => [sample.id, sample.explanation]))
  };

  fs.writeFileSync(PROBLEMS_PATH, `${JSON.stringify(nextProblems, null, 2)}\n`);
  fs.writeFileSync(EXPLANATIONS_PATH, `${JSON.stringify(nextExplanations, null, 2)}\n`);
  writeChineseJuniorSubjectiveQualityReport(incomingProblems);

  console.log(`Upserted ${incomingProblems.length} subjective sample problem(s) from ${SOURCE_COLLECTION}.`);
  console.log(`Problem bank now has ${nextProblems.length} problem(s).`);
  console.log(`Example explanations now has ${Object.keys(nextExplanations).length} template(s).`);
  console.log(`CN junior subjective quality report: ${path.relative(process.cwd(), QUALITY_REPORT_PATH)}`);
}

type QualityProfile = {
  difficulty: number;
  layer: NonNullable<Problem["taxonomy"]>["layer"];
  stage: NonNullable<Problem["taxonomy"]>["stage"];
};

function stratifyChineseSubjectiveProblems(problems: Problem[]): Problem[] {
  const groups = new Map<string, Problem[]>();

  problems.filter(isChineseSubjectiveProblem).forEach((problem) => {
    const chapter = problem.curriculum.chapter;
    groups.set(chapter, [...(groups.get(chapter) ?? []), problem]);
  });

  const stratified = new Map<string, Problem>();

  groups.forEach((chapterProblems) => {
    const ordered = [...chapterProblems].sort(compareForQualityStratification);
    ordered.forEach((problem, index) => {
      const profile = qualityProfileForProblem(problem, index, ordered.length);
      stratified.set(problem.id, {
        ...problem,
        difficulty: profile.difficulty,
        taxonomy: {
          ...problem.taxonomy,
          version: "v0",
          layer: profile.layer,
          stage: profile.stage,
    problemType: problem.taxonomy?.problemType ?? "cn_subjective_written_response",
          cognitiveTags: qualityCognitiveTags(problem, profile),
          estimatedTimeSeconds: qualityEstimatedTime(problem, profile)
        }
      });
    });
  });

  return problems.map((problem) => stratified.get(problem.id) ?? problem);
}

function compareForQualityStratification(left: Problem, right: Problem) {
  const leftModeWeight = modeWeight(left.responseSchema?.mode);
  const rightModeWeight = modeWeight(right.responseSchema?.mode);

  return (
    (left.difficulty ?? 3) - (right.difficulty ?? 3) ||
    leftModeWeight - rightModeWeight ||
    (left.curriculum.sequence ?? 0) - (right.curriculum.sequence ?? 0) ||
    left.id.localeCompare(right.id)
  );
}

function modeWeight(mode: SubjectiveResponseSchema["mode"] | undefined) {
  if (mode === "application") return 1;
  if (mode === "constructed_response") return 2;
  if (mode === "proof") return 3;
  return 2;
}

function qualityProfileForProblem(problem: Problem, index: number, total: number): QualityProfile {
  const baseStage = problem.taxonomy?.stage ?? "Bridge";
  const position = Math.floor((index / Math.max(total, 1)) * 8);

  if (position <= 1) {
    return {
      difficulty: 2,
      layer: "Foundation",
      stage: baseStage
    };
  }

  if (position <= 4) {
    return {
      difficulty: 3,
      layer: "Standard",
      stage: baseStage
    };
  }

  if (position <= 6) {
    return {
      difficulty: 4,
      layer: "Honors",
      stage: baseStage
    };
  }

  return challengeProfile(problem, baseStage);
}

function challengeProfile(
  problem: Problem,
  baseStage: NonNullable<Problem["taxonomy"]>["stage"]
): QualityProfile {
  if (problem.concepts.includes("counting_probability")) {
    return {
      difficulty: 4,
      layer: "AMC8",
      stage: "AMC8 Transfer"
    };
  }

  if (problem.responseSchema?.mode === "proof") {
    return {
      difficulty: 5,
      layer: "Honors",
      stage: "Bridge"
    };
  }

  if (baseStage === "Algebra Readiness") {
    return {
      difficulty: 5,
      layer: "Honors",
      stage: "Algebra Readiness"
    };
  }

  return {
    difficulty: 4,
    layer: "Honors",
    stage: baseStage
  };
}

function qualityCognitiveTags(problem: Problem, profile: QualityProfile) {
  const tags = new Set(problem.taxonomy?.cognitiveTags ?? []);

  if (profile.layer === "Foundation") tags.add("foundation_fluency");
  if (profile.layer === "Standard") tags.add("core_method");
  if (profile.layer === "Honors") tags.add(problem.responseSchema?.mode === "proof" ? "proof_closure" : "multi_step_reasoning");
  if (profile.layer === "AMC8") tags.add("transfer");

  return [...tags];
}

function qualityEstimatedTime(problem: Problem, profile: QualityProfile) {
  const current = problem.taxonomy?.estimatedTimeSeconds ?? 300;
  const modeFloor = problem.responseSchema?.mode === "proof" ? 360 : problem.responseSchema?.mode === "application" ? 320 : 280;
  const layerFloor = profile.layer === "Foundation" ? 240 : profile.layer === "Standard" ? 300 : 360;

  return Math.max(current, modeFloor, layerFloor);
}

function writeChineseJuniorSubjectiveQualityReport(problems: Problem[]) {
  const items = problems.filter(isChineseJuniorSubjectiveProblem);
  const chapterRows = chapterQualityRows(items);
  const layerTotals = countBy(items, (problem) => problem.taxonomy?.layer ?? "unknown");
  const stageTotals = countBy(items, (problem) => problem.taxonomy?.stage ?? "unknown");
  const difficultyTotals = countBy(items, (problem) => String(problem.difficulty));
  const modeTotals = countBy(items, (problem) => problem.responseSchema?.mode ?? "unknown");
  const metTarget = chapterRows.filter((row) => row.status === "balanced").length;

  fs.mkdirSync(path.dirname(QUALITY_REPORT_PATH), { recursive: true });
  fs.writeFileSync(
    QUALITY_REPORT_PATH,
    [
      "# CN Junior Subjective Quality Layer Report v0",
      "",
      `Generated at: ${new Date().toISOString()}`,
      "",
      "## Summary",
      "",
      `- Chinese junior subjective problems: ${items.length}`,
      `- Chapters: ${chapterRows.length}`,
      `- Balanced chapter profiles: ${metTarget}/${chapterRows.length}`,
      "",
      "The quality layer now treats each chapter as a small ladder: two foundation checks, three standard core-method tasks, two honors multi-step tasks, and one chapter-appropriate challenge slot. Probability chapters use the challenge slot as AMC8 Transfer. Algebra readiness and proof-heavy chapters keep the challenge within their natural stage instead of forcing an artificial competition label.",
      "",
      "## Overall Distribution",
      "",
      "### Layers",
      "",
      toMarkdownTable(["Layer", "Problems"], entries(layerTotals).map(([key, value]) => [key, String(value)])),
      "",
      "### Stages",
      "",
      toMarkdownTable(["Stage", "Problems"], entries(stageTotals).map(([key, value]) => [key, String(value)])),
      "",
      "### Difficulty",
      "",
      toMarkdownTable(["Difficulty", "Problems"], entries(difficultyTotals).map(([key, value]) => [key, String(value)])),
      "",
      "### Response Modes",
      "",
      toMarkdownTable(["Mode", "Problems"], entries(modeTotals).map(([key, value]) => [key, String(value)])),
      "",
      "## Chapter Profiles",
      "",
      toMarkdownTable(
        ["Grade", "Chapter", "Count", "Layers", "Stages", "Difficulty", "Modes", "Status"],
        chapterRows.map((row) => [
          row.grade,
          row.chapterTitle,
          String(row.count),
          formatCounts(row.layers),
          formatCounts(row.stages),
          formatCounts(row.difficulties),
          formatCounts(row.modes),
          row.status
        ])
      ),
      "",
      "## Next Decision",
      "",
      "Use this report before horizontal expansion. Chapters marked balanced are ready for more volume; any chapter that later drifts should be normalized before adding another batch.",
      ""
    ].join("\n")
  );
}

function chapterQualityRows(items: Problem[]) {
  const groups = new Map<string, Problem[]>();

  items.forEach((problem) => {
    const key = problem.curriculum.chapter;
    groups.set(key, [...(groups.get(key) ?? []), problem]);
  });

  return [...groups.values()]
    .map((chapterItems) => {
      const first = chapterItems[0];
      const layers = countBy(chapterItems, (problem) => problem.taxonomy?.layer ?? "unknown");
      const stages = countBy(chapterItems, (problem) => problem.taxonomy?.stage ?? "unknown");
      const difficulties = countBy(chapterItems, (problem) => String(problem.difficulty));
      const modes = countBy(chapterItems, (problem) => problem.responseSchema?.mode ?? "unknown");
      const isBalanced =
        chapterItems.length >= 8 &&
        (layers.Foundation ?? 0) >= 2 &&
        (layers.Standard ?? 0) >= 3 &&
        ((layers.Honors ?? 0) + (layers.AMC8 ?? 0) + (layers["AMC8 Stretch"] ?? 0)) >= 3;

      return {
        chapterTitle: first.curriculum.chapterTitle,
        count: chapterItems.length,
        difficulties,
        grade: getChineseGrade(first),
        layers,
        modes,
        stages,
        status: isBalanced ? "balanced" : "needs review"
      };
    })
    .sort((a, b) => a.grade.localeCompare(b.grade) || a.chapterTitle.localeCompare(b.chapterTitle));
}

function isChineseJuniorSubjectiveProblem(problem: Problem) {
  return isChineseSubjectiveProblem(problem) && problem.curriculum?.course === "CN Junior High Math";
}

function isChineseSubjectiveProblem(problem: Problem) {
  return (
    problem.curriculum?.sourceCollection === SOURCE_COLLECTION &&
    (problem.curriculum?.course === "CN Junior High Math" || problem.curriculum?.course === "CN Senior High Math") &&
    problem.locale?.language === "zh" &&
    problem.answerType === "manual"
  );
}

function getChineseGrade(problem: Problem) {
  const match = problem.curriculum.chapterTitle.match(/([七八九])年级/);
  return match ? `${match[1]}年级` : "未分级";
}

function countBy<T>(items: T[], getKey: (item: T) => string) {
  return items.reduce<Record<string, number>>((counts, item) => {
    const key = getKey(item);
    counts[key] = (counts[key] ?? 0) + 1;
    return counts;
  }, {});
}

function entries(record: Record<string, number>) {
  return Object.entries(record).sort(([left], [right]) => left.localeCompare(right));
}

function formatCounts(record: Record<string, number>) {
  return entries(record)
    .map(([key, value]) => `${key}:${value}`)
    .join(", ");
}

function toMarkdownTable(headers: string[], rows: string[][]) {
  return [
    `| ${headers.join(" | ")} |`,
    `| ${headers.map(() => "---").join(" | ")} |`,
    ...rows.map((row) => `| ${row.map(escapeMarkdownCell).join(" | ")} |`)
  ].join("\n");
}

function escapeMarkdownCell(value: string) {
  return value.replace(/\|/g, "\\|");
}

function subjectiveSchema(
  mode: SubjectiveResponseSchema["mode"],
  rubric: SubjectiveResponseSchema["rubric"]
): SubjectiveResponseSchema {
  return {
    version: "v0",
    mode,
    requiresWork: true,
    acceptedInputs,
    rubric,
    reviewPolicy: {
      aiAssist: true,
      autoGrade: false,
      humanReview: true
    }
  };
}

function rubricForMode(mode: SubjectiveResponseSchema["mode"]) {
  if (mode === "application") return applicationRubric;
  if (mode === "proof") return proofRubric;
  return constructedRubric;
}

function taxonomy(
  layer: NonNullable<Problem["taxonomy"]>["layer"],
  stage: NonNullable<Problem["taxonomy"]>["stage"],
  problemType: string,
  cognitiveTags: string[],
  estimatedTimeSeconds: number
): NonNullable<Problem["taxonomy"]> {
  return {
    version: "v0",
    layer,
    stage,
    problemType,
    cognitiveTags,
    estimatedTimeSeconds
  };
}

function curriculum(
  course: string,
  theme: string,
  chapter: string,
  chapterTitle: string,
  sequence: number
): Problem["curriculum"] {
  return {
    course,
    theme,
    chapter,
    chapterTitle,
    sequence,
    sourceCollection: SOURCE_COLLECTION
  };
}

function locale(
  language: NonNullable<Problem["locale"]>["language"],
  curriculumSystem: NonNullable<Problem["locale"]>["curriculumSystem"],
  displayTrack: string,
  gradeBand: string,
  contentStatus: NonNullable<Problem["locale"]>["contentStatus"]
): NonNullable<Problem["locale"]> {
  return {
    language,
    curriculumSystem,
    region: language === "zh" ? "CN" : "US",
    displayTrack,
    gradeBand,
    contentStatus
  };
}

function readJson<T>(filePath: string): T {
  return JSON.parse(fs.readFileSync(filePath, "utf8")) as T;
}

main();
